package net.civeira.phylax.feature.identity.userprofile.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.userprofile.domain.UserProfile;
import net.civeira.phylax.feature.identity.userprofile.domain.valueobject.GivenNameVO;

class GivenNameValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of given name of user profile")
  void test_given_name_value_holder_assign_plain_value() {
    Object holder = new Object();
    GivenNameValueHolder<Object> value = new GivenNameValueHolder<>(holder);
    Assertions.assertSame(holder, value.givenName("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getGivenNameValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getGivenName().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.givenNameNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getGivenNameValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getGivenName().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of given name of user profile")
  void test_given_name_value_holder_assign_value_object() {
    Object holder = new Object();
    GivenNameValueHolder<Object> value = new GivenNameValueHolder<>(holder);
    GivenNameVO vo = GivenNameVO.from("one");
    Assertions.assertFalse(value.getGivenNameValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.givenName(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getGivenNameValue().orElseThrow());
    Assertions.assertSame(holder, value.givenName(Optional.empty()));
    Assertions.assertFalse(value.getGivenNameValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.givenName(Optional.of(vo)));
    Assertions.assertSame(vo, value.getGivenNameValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of given name of user profile against the original")
  void test_given_name_value_holder_read() {
    Object holder = new Object();
    GivenNameValueHolder<Object> value = new GivenNameValueHolder<>(holder);
    GivenNameVO vo = GivenNameVO.from("one");
    GivenNameVO other = GivenNameVO.from("one");
    UserProfile original = Mockito.mock(UserProfile.class);
    Mockito.when(original.getGivenNameValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readGivenName(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readGivenName(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.givenName(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readGivenName(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readGivenName(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of given name of user profile")
  void test_given_name_value_holder_unset() {
    Object holder = new Object();
    GivenNameValueHolder<Object> value = new GivenNameValueHolder<>(holder);
    GivenNameVO vo = GivenNameVO.from("one");
    value.givenName(vo);
    Assertions.assertSame(holder, value.unsetGivenNameIfMatches("givenName_other"));
    Assertions.assertTrue(value.getGivenNameValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetGivenNameIfMatches("givenName"));
    Assertions.assertFalse(value.getGivenNameValue().isPresent(),
        "The field name must clear the value");
    value.givenName(vo);
    Assertions.assertSame(holder, value.unsetGivenName());
    Assertions.assertFalse(value.getGivenNameValue().isPresent(), "Unset must clear the value");
  }
}
